package com.hbm.machine.gascentrifuge;
import com.hbm.item.battery.*;import com.hbm.item.fluid.FluidIdentifier;import com.hbm.machine.electricfurnace.FurnaceUpgradeItem;import com.hbm.machine.centrifuge.OverdriveUpgradeItem;import com.hbm.machine.crystallizer.EffectUpgradeItem;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
public final class GasCentrifugeMenu extends AbstractContainerMenu {
 public final Container machine;private final BlockPos position;public GasCentrifugeMenu(int id,Inventory player,RegistryFriendlyByteBuf buffer){this(id,player,buffer.readBlockPos());}private GasCentrifugeMenu(int id,Inventory player,BlockPos pos){this(id,player,player.player.level().getBlockEntity(pos) instanceof GasCentrifugeBlockEntity m?m:new SimpleContainer(7),pos);}public GasCentrifugeMenu(int id,Inventory player,Container machine,BlockPos pos){super(GasCentrifugeContent.MENU.get(),id);checkContainerSize(machine,7);this.machine=machine;position=pos;machine.startOpen(player.player);for(int i=0;i<2;i++)for(int j=0;j<2;j++)addSlot(new com.hbm.recipe.generic.GenericOutputSlot(player.player,machine,j+i*2,71+j*18,53+i*18));addSlot(new Slot(machine,4,182,71));addSlot(new Slot(machine,5,91,15));addSlot(new Slot(machine,6,69,15));for(int i=0;i<3;i++)for(int j=0;j<9;j++)addSlot(new Slot(player,j+i*9+9,8+j*18,122+i*18));for(int j=0;j<9;j++)addSlot(new Slot(player,j,8+j*18,180));}
 public BlockPos position(){return position;}@Override public boolean stillValid(Player player){return machine.stillValid(player);}@Override public void removed(Player player){super.removed(player);machine.stopOpen(player);}@Override public ItemStack quickMoveStack(Player player,int index){var slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;var current=slot.getItem();var before=current.copy();boolean moved;if(index<=6)moved=moveItemStackTo(current,7,slots.size(),true);else if(current.getItem() instanceof HbmBattery||current.getItem() instanceof CreativeBatteryItem)moved=moveItemStackTo(current,4,5,false);else if(current.getItem() instanceof FluidIdentifier)moved=moveItemStackTo(current,5,6,false);else if(isUpgrade(current))moved=moveItemStackTo(current,6,7,false);else return ItemStack.EMPTY;if(!moved)return ItemStack.EMPTY;if(current.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();return before;}
 /** Existing true upgrade families share source ItemMachineUpgrade identity; only GC item actually speeds this machine. */
 public static boolean isUpgrade(ItemStack stack){return com.hbm.machine.precisionassembler.PrecisionUpgrades.isUpgrade(stack);}
}
